input.content:
server {
    listen 8080;
    server_name localhost;

    root /var/www/html;
    index index.html;

    access_log /var/log/nginx/benchmark-access.log benchmark;
    error_log /var/log/nginx/benchmark-error.log;

    limit_req zone=benchmark_limit burst=10 nodelay;

    location / {
        try_files $uri $uri/ =404;
    }

    error_page 404 /404.html;
    location = /404.html {
        internal;
    }
}

steps.command:
nginx -t && (nginx -s reload 2>/dev/null || nginx) && sleep 1 && printf '--- index ---
' && curl -s -o /dev/null -w 'status=%{http_code}
' http://localhost:8080/ && curl -s http://localhost:8080/ && printf '--- 404 ---
' && curl -s -o /dev/null -w 'status=%{http_code}
' http://localhost:8080/nope && curl -s http://localhost:8080/nope && printf '--- logs ---
' && cat /var/log/nginx/benchmark-access.log
